const VerifyRequest = (function () {
  const module = { exports: {} };
  /**
   * verify-request: التحقق من طلب التطبيق قبل أي عمل (عقد n8n، الإصدار v1).
   *
   * دالة نقية: لا شبكة ولا ساعة ولا حالة عامة. الوقت والحالة يُمرَّران ويُعادان.
   * تُضمَّن هذه الشيفرة حرفيًّا في عقدة Code، ويستوردها vitest كما هي.
   * لا استيراد إلا `crypto` المدمجة (NODE_FUNCTION_ALLOW_BUILTIN=crypto).
   *
   * التوقيع المتوقَّع (من العقد):
   *   X-Nx-Sig = "v1=" + hex(HMAC-SHA256(secret,
   *     "nx-n8n:v1|" + ts + "|" + nonce + "|" + path + "|" + sha256hex(body)))
   *
   * الرفض (كلّه يعود 200 مع code=auth_failed من العقدة التي تبني الغلاف):
   *   - انحراف الساعة أكثر من 30 ثانية
   *   - نونس مكرَّر خلال 120 ثانية (السقف 5000 مدخل)
   *   - بصمة المتن أو التوقيع لا يطابق
   *
   * ترتيب الفحوص مقصود: التوقيع أولًا ثم التكرار. النونس لا يُسجَّل إلا بعد
   * توقيع صحيح، وإلا ملأ مهاجمٌ بلا مفتاح مخزن النونس وطرد نونسات حقيقية.
   *
   * المتن: العقدة الأصلية تمرّر المتن الخام (base64) إن توفّر، وإلا يُعاد تسلسل
   * المتن المحلَّل بـJSON.stringify. المسار الثاني مكافئ دلاليًّا لما سيُعالَج،
   * ويطابق ما يُرسله التطبيق إن بُني المتن بـJSON.stringify. لم يُقَس على n8n حقيقي.
   */
  const crypto = require("crypto");

  const KEY_ID = "v1";
  const SKEW_MS = 30000;
  const NONCE_TTL_MS = 120000;
  const NONCE_CAP = 5000;
  const MIN_SECRET_LENGTH = 32;
  const NONCE_RE = /^[0-9a-f]{32}$/;
  const SIG_RE = /^v1=[0-9a-f]{64}$/;
  const TS_RE = /^[0-9]{1,12}$/;
  const MAX_DEADLINE_MS = 120000;

  function sha256hex(text) {
    return crypto.createHash("sha256").update(String(text), "utf8").digest("hex");
  }

  function hmacHex(secret, text) {
    return crypto.createHmac("sha256", secret).update(String(text), "utf8").digest("hex");
  }

  function headerValue(headers, name) {
    if (!headers || typeof headers !== "object") return "";
    const wanted = String(name).toLowerCase();
    for (const key of Object.keys(headers)) {
      if (key.toLowerCase() === wanted) {
        const value = Array.isArray(headers[key]) ? headers[key][0] : headers[key];
        return typeof value === "string" ? value.trim() : "";
      }
    }
    return "";
  }

  function constantTimeEqual(a, b) {
    const left = Buffer.from(String(a), "utf8");
    const right = Buffer.from(String(b), "utf8");
    if (left.length !== right.length) return false;
    return crypto.timingSafeEqual(left, right);
  }

  /** يُسقط المنتهي ويعيد نسخة جديدة؛ لا يعدّل المدخل. */
  function pruneNonces(store, now) {
    const next = {};
    if (!store || typeof store !== "object") return next;
    for (const key of Object.keys(store)) {
      const expiresAt = store[key];
      if (typeof expiresAt === "number" && expiresAt > now && NONCE_RE.test(key)) {
        next[key] = expiresAt;
      }
    }
    return next;
  }

  /** يضيف نونسًا ويطرد الأقدم عند بلوغ السقف. يعيد المخزن الجديد وعدد المطرودين. */
  function rememberNonce(store, nonce, now) {
    const next = pruneNonces(store, now);
    let evicted = 0;
    const keys = Object.keys(next);
    if (keys.length >= NONCE_CAP) {
      keys.sort((a, b) => next[a] - next[b]);
      const drop = keys.length - NONCE_CAP + 1;
      for (let i = 0; i < drop; i += 1) {
        delete next[keys[i]];
        evicted += 1;
      }
    }
    next[nonce] = now + NONCE_TTL_MS;
    return { store: next, evicted };
  }

  function canonicalText(body) {
    const text = JSON.stringify(body);
    return typeof text === "string" ? text : "";
  }

  /**
   * المتن الخام يُقبل مرشَّحًا فقط إن كان JSON يطابق المتن المحلَّل دلاليًّا.
   * في نمط التخزين على القرص قد يحمل الحقل معرّفًا لا محتوى، فيسقط هنا بدل أن
   * يُرفض كل طلب سليم.
   */
  function rawCandidate(rawBodyBase64, body) {
    if (typeof rawBodyBase64 !== "string" || rawBodyBase64.length === 0) return null;
    try {
      const text = Buffer.from(rawBodyBase64, "base64").toString("utf8");
      if (JSON.stringify(JSON.parse(text)) !== canonicalText(body)) return null;
      return text;
    } catch (error) {
      return null;
    }
  }

  function fail(reason, nonces) {
    return {
      ok: false,
      code: reason === "no_secret" ? "internal" : "auth_failed",
      reason,
      nonces,
      nonce: "",
      ts: 0,
      deadlineMs: null,
      bodySource: "",
      evicted: 0,
    };
  }

  /**
   * @param {object} input
   * @param {object} input.headers رؤوس الطلب (أي حالة أحرف)
   * @param {*} input.body المتن المحلَّل
   * @param {string} [input.rawBodyBase64] المتن الخام إن توفّر
   * @param {string} input.path المسار المغلق لهذا الـworkflow (ثابت لا من الطلب)
   * @param {string} input.secret السر (32 حرفًا فأكثر)
   * @param {number} input.now الوقت بالميللي ثانية
   * @param {object} [input.nonces] مخزن النونس {nonce: expiresAtMs}
   */
  function evaluate(input) {
    const now =
      input && typeof input.now === "number" && isFinite(input.now) ? input.now : Date.now();
    let nonces = pruneNonces(input && input.nonces, now);
    try {
      // السرّ يُقصّ من الفراغات والأسطر حول طرفيه كما يفعل التطبيق (`parseSecret` في config.server.ts):
      // سطرٌ ختاميّ ملصوق مع السرّ في أحد الطرفين كان يُسقط كل طلب بصمت (توقيعان لسرّين مختلفين).
      const rawSecret = input && input.secret;
      const secret = typeof rawSecret === "string" ? rawSecret.trim() : rawSecret;
      if (typeof secret !== "string" || secret.length < MIN_SECRET_LENGTH) {
        return fail("no_secret", nonces);
      }
      const path = input && typeof input.path === "string" ? input.path : "";
      if (!path) return fail("bad_path", nonces);

      const headers = input.headers;
      if (headerValue(headers, "x-nx-key-id") !== KEY_ID) return fail("bad_key_id", nonces);

      const tsText = headerValue(headers, "x-nx-ts");
      if (!TS_RE.test(tsText)) return fail("bad_ts", nonces);
      const ts = Number(tsText);
      // بالثواني الكاملة كما يفعل التطبيق (`verifyRequestSignature`): الختم ثوانٍ صحيحة، ومقارنته بالمللي ثانية
      // كانت ترفض ما يقبله التطبيق في الثانية التي تلي الثلاثين (ساعة n8n متقدّمة 30.0 إلى 30.999 ث).
      if (Math.abs(Math.floor(now / 1000) - ts) > SKEW_MS / 1000) return fail("skew", nonces);

      const nonce = headerValue(headers, "x-nx-nonce").toLowerCase();
      if (!NONCE_RE.test(nonce)) return fail("bad_nonce", nonces);

      const signature = headerValue(headers, "x-nx-sig").toLowerCase();
      if (!SIG_RE.test(signature)) return fail("bad_signature_format", nonces);

      const candidates = [];
      const raw = rawCandidate(input.rawBodyBase64, input.body);
      if (raw !== null) candidates.push({ source: "raw", text: raw });
      candidates.push({ source: "canonical", text: canonicalText(input.body) });

      let matched = "";
      for (const candidate of candidates) {
        const expected =
          "v1=" +
          hmacHex(
            secret,
            "nx-n8n:v1|" + ts + "|" + nonce + "|" + path + "|" + sha256hex(candidate.text),
          );
        if (constantTimeEqual(expected, signature) && matched === "") matched = candidate.source;
      }
      if (matched === "") return fail("bad_signature", nonces);

      if (nonces[nonce] !== undefined) return fail("replay", nonces);
      const remembered = rememberNonce(nonces, nonce, now);
      nonces = remembered.store;

      const deadlineText = headerValue(headers, "x-nx-deadline-ms");
      let deadlineMs = null;
      if (/^[0-9]{1,6}$/.test(deadlineText)) {
        const parsed = Number(deadlineText);
        if (parsed >= 1 && parsed <= MAX_DEADLINE_MS) deadlineMs = parsed;
      }

      return {
        ok: true,
        code: "ok",
        reason: "",
        nonces,
        nonce,
        ts,
        deadlineMs,
        bodySource: matched,
        evicted: remembered.evicted,
      };
    } catch (error) {
      return fail("exception", nonces);
    }
  }

  const UUID_RE = /^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$/i;

  /**
   * النونس ومعرّف الطلب «كما ادّعاهما المرسل»، بصرف النظر عن صحة التوقيع. يُوقَّع بهما
   * ردّ الفشل ليقرأ التطبيق auth_failed بدل أن يُسقطه. ليسا موثوقين ولا يُستعملان
   * قرارًا: النونس هنا لا يُسجَّل، وإنما يوقَّع به الجواب فقط.
   */
  function claimedContext(input) {
    const out = { nonce: "", requestId: "" };
    try {
      const nonce = headerValue(input && input.headers, "x-nx-nonce").toLowerCase();
      if (NONCE_RE.test(nonce)) out.nonce = nonce;
      const body = input && input.body;
      if (body && typeof body === "object" && UUID_RE.test(String(body.requestId))) {
        out.requestId = body.requestId;
      }
    } catch (error) {
      // يبقى فارغًا
    }
    return out;
  }

  function verifyRequest(input) {
    const result = evaluate(input);
    const claimed = claimedContext(input);
    result.claimedNonce = claimed.nonce;
    result.claimedRequestId = claimed.requestId;
    return result;
  }

  if (typeof module !== "undefined" && module.exports) {
    module.exports = {
      verifyRequest,
      rememberNonce,
      pruneNonces,
      sha256hex,
      hmacHex,
      SKEW_MS,
      NONCE_TTL_MS,
      NONCE_CAP,
      MIN_SECRET_LENGTH,
    };
  }
  return module.exports;
})();

const SignResponse = (function () {
  const module = { exports: {} };
  /**
   * sign-response: توقيع ردّ n8n للتطبيق (عقد n8n، الإصدار v1).
   *
   *   X-Nx-Resp-Ts  = ثوانٍ يونكس
   *   X-Nx-Resp-Sig = "v1=" + hex(HMAC-SHA256(secret,
   *     "nx-n8n:v1:resp|" + respTs + "|" + requestNonce + "|" + sha256hex(responseBody)))
   *
   * التطبيق يُسقط أي ردّ يفشل توقيعه أو طابعه الزمني (انحراف أكثر من 30 ثانية)،
   * وهذا يلتقط أيضًا عنوانًا موجَّهًا إلى خدمة خطأ.
   *
   * دالة نقية: الوقت يُمرَّر. بلا سر صالح يعود الردّ بلا ترويسات توقيع (التطبيق
   * سيُسقطه) ولا يُرمى خطأ أبدًا.
   *
   * `signRequest` جهة العميل: يستعملها الاختبار وسكربت المثال فقط، ولا تُستدعى
   * في أي عقدة. هي نسخة ثانية من صيغة التطبيق تُقارَن بمتجهات ذهبية مستقلة.
   */
  const crypto = require("crypto");

  const MIN_SECRET_LENGTH = 32;

  function sha256hex(text) {
    return crypto.createHash("sha256").update(String(text), "utf8").digest("hex");
  }

  function hmacHex(secret, text) {
    return crypto.createHmac("sha256", secret).update(String(text), "utf8").digest("hex");
  }

  /**
   * @param {object} input
   * @param {string} input.secret
   * @param {string} input.body نص الردّ كما سيُرسَل حرفيًّا
   * @param {string} input.nonce نونس الطلب
   * @param {number} input.now الوقت بالميللي ثانية
   * @returns {{signed: boolean, respTs: string, respSig: string, headers: object}}
   */
  function signResponse(input) {
    const now =
      input && typeof input.now === "number" && isFinite(input.now) ? input.now : Date.now();
    const respTs = String(Math.floor(now / 1000));
    try {
      // مقصوص كما في التطبيق (`parseSecret`) وكما في verify-request: الطرفان يوقّعان بالبايتات نفسها.
      const rawSecret = input && input.secret;
      const secret = typeof rawSecret === "string" ? rawSecret.trim() : rawSecret;
      if (typeof secret !== "string" || secret.length < MIN_SECRET_LENGTH) {
        return { signed: false, respTs, respSig: "", headers: {} };
      }
      const body = typeof input.body === "string" ? input.body : "";
      const nonce = typeof input.nonce === "string" ? input.nonce : "";
      const respSig =
        "v1=" + hmacHex(secret, "nx-n8n:v1:resp|" + respTs + "|" + nonce + "|" + sha256hex(body));
      return {
        signed: true,
        respTs,
        respSig,
        headers: { "X-Nx-Resp-Ts": respTs, "X-Nx-Resp-Sig": respSig },
      };
    } catch (error) {
      return { signed: false, respTs, respSig: "", headers: {} };
    }
  }

  /** جهة العميل: يبني ترويسات طلب موقَّعة لنصّ متن محدَّد. */
  function signRequest(input) {
    const ts = String(input.ts);
    const nonce = String(input.nonce);
    const body = String(input.body);
    const sig =
      "v1=" +
      hmacHex(
        input.secret,
        "nx-n8n:v1|" + ts + "|" + nonce + "|" + input.path + "|" + sha256hex(body),
      );
    return {
      "Content-Type": "application/json",
      "X-Nx-Key-Id": "v1",
      "X-Nx-Ts": ts,
      "X-Nx-Nonce": nonce,
      "X-Nx-Deadline-Ms": String(input.deadlineMs === undefined ? 1800 : input.deadlineMs),
      "X-Nx-Sig": sig,
    };
  }

  /** جهة العميل: يتحقق من توقيع ردّ (للاختبار وسكربت المثال). */
  function verifyResponse(input) {
    const respTs = String(input.respTs);
    const expected =
      "v1=" +
      hmacHex(
        input.secret,
        "nx-n8n:v1:resp|" + respTs + "|" + input.nonce + "|" + sha256hex(input.body),
      );
    const skewMs = Math.abs(input.now - Number(respTs) * 1000);
    return { ok: expected === input.respSig && skewMs <= 30000, skewMs };
  }

  if (typeof module !== "undefined" && module.exports) {
    module.exports = { signResponse, signRequest, verifyResponse, sha256hex, hmacHex };
  }
  return module.exports;
})();

const checks = [];
const check = (name, ok) => checks.push({ name, ok: Boolean(ok) });
const prior = (() => {
  try {
    return $input.first().json.checks || [];
  } catch (e) {
    return [];
  }
})();

const SECRET = "0123456789abcdef0123456789abcdef";
const NONCE = "00112233445566778899aabbccddeeff";
const PATH = "sadeed-research-v1";
const GOLDEN_REQ = "v1=cd86c695120c61381321c00931d287e01d9c558f5559949c3cf88476a8a5b253";
const GOLDEN_RESP = "v1=cd5eb20be2c70ebfd4aa6fbc13188d97400ca8b6d181bf48b3949675dc6ba6d2";
const TS = 1761800000;
const body = { v: 1 };
const headers = (sig) => ({
  "x-nx-key-id": "v1",
  "x-nx-ts": String(TS),
  "x-nx-nonce": NONCE,
  "x-nx-sig": sig,
});
const signed = SignResponse.signRequest({ secret: SECRET, path: PATH, body: JSON.stringify(body), ts: TS, nonce: NONCE });
check("طلب موقَّع يطابق المتجه الذهبي", signed["X-Nx-Sig"] === GOLDEN_REQ);
const ok1 = VerifyRequest.verifyRequest({ headers: headers(GOLDEN_REQ), body, path: PATH, secret: SECRET, now: TS * 1000, nonces: {} });
check("التحقق يقبل الطلب السليم", ok1.ok === true);
const replay = VerifyRequest.verifyRequest({ headers: headers(GOLDEN_REQ), body, path: PATH, secret: SECRET, now: TS * 1000 + 1000, nonces: ok1.nonces });
check("النونس المكرَّر يُرفض", replay.ok === false && replay.reason === "replay");
const skew = VerifyRequest.verifyRequest({ headers: headers(GOLDEN_REQ), body, path: PATH, secret: SECRET, now: TS * 1000 + 31000, nonces: {} });
check("انحراف الساعة فوق 30 ثانية يُرفض", skew.ok === false && skew.reason === "skew");
const tampered = VerifyRequest.verifyRequest({ headers: headers(GOLDEN_REQ), body: { v: 2 }, path: PATH, secret: SECRET, now: TS * 1000, nonces: {} });
check("المتن المعبوث به يُرفض", tampered.ok === false);
const wrongPath = VerifyRequest.verifyRequest({ headers: headers(GOLDEN_REQ), body, path: "fnn-runner-v1", secret: SECRET, now: TS * 1000, nonces: {} });
check("التوقيع مرتبط بالمسار", wrongPath.ok === false);
const resp = SignResponse.signResponse({ secret: SECRET, body: '{"v":1,"ok":true}', nonce: NONCE, now: 1761800001000 });
check("توقيع الردّ يطابق المتجه الذهبي", resp.respSig === GOLDEN_RESP);
const noSecret = SignResponse.signResponse({ secret: "", body: "x", nonce: NONCE, now: TS * 1000 });
check("بلا سرّ صالح لا يُوقَّع الردّ", noSecret.signed === false);

return [{ json: { checks: prior.concat(checks) } }];

const PlanQueries = (function () {
  const module = { exports: {} };
  /**
   * plan-queries: يحوّل «الموجز» (كلمات ورموز لا الجملة الخام) إلى طلبات للمزوّدين.
   *
   * نقية: لا شبكة. تُنتج كائن خطّة تقرؤه عقد البوّابة والطلبات. لا تجلب صفحات:
   * المزوّدون يعيدون مقتطفات (snippets) فقط، ولا مسار هنا لتحميل صفحة أو لكشط
   * HTML أي محرّك بحث. كل عنوان يُبنى من ثوابت هذا الملف + نصّ مُرمَّز.
   *
   * وضع regulatory (سَدِيد، المادة ٩: المصادر غير الرسمية للوائح محظورة): جوجل وTavily
   * يُقيَّدان بالنطاقات الرسمية، ولا يُستدعى Brave ولا مزوّد بلا مفتاح (ويكيبيديا وأخواتها
   * مرجعية لا رسمية)، ويُسقط merge-rank أي نتيجة من غير النطاقات الرسمية والحكومية
   * السعودية. القائمة هنا مرجع النقل لا مرجع الحكم: التطبيق يعيد حساب الطبقة من جدوله.
   *
   * المزوّدون بمفتاح يُستدعَون بالتتابع (n8n ينفّذ فروع المخرج الواحد واحدًا بعد آخر، من
   * الأعلى يسارًا)، فالموعد الداخلي لا يُحفظ بمهلة ثابتة بل بميزانية متبقّية: كل بوّابة
   * تحسب ما بقي من الموعد (بعد حجز ذيل للدفعة الأخيرة بلا مفتاح) وتسلّم مهلة النداء
   * (timeoutMs) فتقصر المهلة كلما استُهلك الوقت، ولا يبدأ نداء يقلّ ما بقي له عن
   * الحدّ الأدنى MIN_CALL_MS.
   *
   * التنظيف: الحدود والاقتباس والنقطتان تُزال من الكلمات حتى لا يصير مدخلٌ
   * مثل `site:evil.com` عامل بحث. محتوى الويب غير موثوق، وهذا الملف لا يثق بالموجز
   * أيضًا (الموجز يبنيه التطبيق، لكن الفحص هنا دفاع إضافي).
   */

  /** أقل مهلة تستحق بها محاولة نداء. ما دونها يُتخطّى بحالة timeout بزمن صفر. */
  const MIN_CALL_MS = 250;
  /** ذيل من الموعد الداخلي يُحجز لدفعة المزوّدين بلا مفتاح (سريعة وبلا حصة) بعد المزوّدين بمفتاح. */
  const KEYLESS_RESERVE_MS = 350;

  const FLAVORS = {
    sadeed: {
      modes: ["general", "regulatory"],
      singles: ["google", "brave", "tavily"],
      timeoutMs: 1100,
      maxInternalMs: 1500,
    },
    fnn: {
      modes: ["docs", "code", "security", "general"],
      singles: ["google", "brave", "tavily", "github", "osv"],
      timeoutMs: 2500,
      maxInternalMs: 5000,
    },
  };

  const OFFICIAL_REGULATORY_DOMAINS = [
    "hcis.gov.sa",
    "uqn.gov.sa",
    "laws.boe.gov.sa",
    "moi.gov.sa",
    "my.gov.sa",
    "sdaia.gov.sa",
    "nca.gov.sa",
    "zatca.gov.sa",
    "saso.gov.sa",
  ];

  const OFFICIAL_DOCS_DOMAINS = [
    "developer.mozilla.org",
    "nodejs.org",
    "react.dev",
    "typescriptlang.org",
    "tanstack.com",
    "supabase.com",
    "vite.dev",
    "postgresql.org",
