      }
    } catch (error) {
      // يبقى فارغًا
    }
    return out;
  }

  if (typeof module !== "undefined" && module.exports) {
    module.exports = {
      buildEnvelope,
      buildRunnerEnvelope,
      validateEnvelope,
      contextFromWebhook,
      RESEARCH_CODES,
      RUNNER_CODES,
      MAX_BODY_BYTES,
      MAX_PROVIDERS,
    };
  }
  return module.exports;
})();

