    return { ok: true, params: out };
  }

  function pruneStore(store, now) {
    const next = {};
    if (!isPlainObject(store)) return next;
    for (const key of Object.keys(store)) {
      const entry = store[key];
      if (
        isPlainObject(entry) &&
        typeof entry.at === "number" &&
        now - entry.at < IDEMPOTENCY_TTL_MS
      ) {
        next[key] = entry;
      }
    }
    return next;
  }

  /**
   * @param {object} input {body, idemKey, now, store}
   * @returns {{decision: string, workflow: string, params: object|null, requestId: string,
   *   idemKey: string, result: object|null, store: object}}
   */
  function dispatch(input) {
    const now =
      input && typeof input.now === "number" && isFinite(input.now) ? input.now : Date.now();
    const store = pruneStore(input && input.store, now);
    const base = { workflow: "", params: null, requestId: "", idemKey: "", result: null, store };
    const body = input && input.body;
    if (!isPlainObject(body) || body.v !== 1)
      return Object.assign({}, base, { decision: "bad_params" });
    const requestId =
      typeof body.requestId === "string" && UUID_RE.test(body.requestId) ? body.requestId : "";
    if (!requestId) return Object.assign({}, base, { decision: "bad_params" });
    base.requestId = requestId;
    const idemKey = input && typeof input.idemKey === "string" ? input.idemKey.trim() : "";
    if (!IDEM_RE.test(idemKey)) return Object.assign({}, base, { decision: "bad_params" });
    base.idemKey = idemKey;
    if (typeof body.workflow !== "string" || CATALOG.indexOf(body.workflow) === -1) {
      return Object.assign({}, base, { decision: "unknown_workflow" });
    }
    base.workflow = body.workflow;
    const checked = validateParams(body.workflow, body.params);
    if (!checked.ok) return Object.assign({}, base, { decision: "bad_params" });
    base.params = checked.params;
    const seen = store[idemKey];
    if (seen) {
      if (seen.workflow !== body.workflow) return Object.assign({}, base, { decision: "bad_params" });
      return Object.assign({}, base, { decision: "already_done", result: seen.result });
    }
    return Object.assign({}, base, { decision: "run" });
  }

  /** يحفظ نتيجة تنفيذ ناجح تحت مفتاح التكرار. */
  function recordResult(input) {
    const now =
      input && typeof input.now === "number" && isFinite(input.now) ? input.now : Date.now();
    const store = pruneStore(input && input.store, now);
    store[input.idemKey] = { at: now, workflow: input.workflow, result: input.result };
    const keys = Object.keys(store);
    if (keys.length > IDEMPOTENCY_CAP) {
      keys.sort((a, b) => store[a].at - store[b].at);
      for (const key of keys.slice(0, keys.length - IDEMPOTENCY_CAP)) delete store[key];
    }
    return store;
  }

  function sinceDate(now, days) {
    return new Date(now - days * 86400000).toISOString().slice(0, 10);
  }

  /** طلب GET عام لكل معرّف يحتاج API: يعيد {url, headers} أو null. */
  function buildRequest(workflow, params, now, stubBase) {
    const root = stubBase
      ? String(stubBase).replace(/\/+$/, "") + "/api.github.com"
      : "https://api.github.com";
    const headers = {
      Accept: "application/vnd.github+json",
      "X-GitHub-Api-Version": "2022-11-28",
      "User-Agent": "nx-n8n-runner",
    };
    if (workflow === "engineering_digest") {
      return {
        url:
          root +
          "/advisories?type=reviewed&ecosystem=npm&severity=" +
          params.severity +
          "&published=" +
          encodeURIComponent(">=" + sinceDate(now, params.days)) +
          "&sort=published&direction=desc&per_page=10",
        headers,
      };
    }
    if (workflow === "dependency_advisory_scan") {
      return {
        url:
          root +
          "/advisories?type=reviewed&ecosystem=npm&affects=" +
          encodeURIComponent(SCAN_PACKAGES.join(",")) +
          "&published=" +
          encodeURIComponent(">=" + sinceDate(now, params.days)) +
          "&sort=published&direction=desc&per_page=10",
        headers,
      };
    }
    return null;
  }

  function clip(text, max) {
    const chars = Array.from(String(text === undefined || text === null ? "" : text));
    return chars.length <= max ? chars.join("") : chars.slice(0, max - 1).join("") + "…";
  }

  // الوسم بلا < داخله فالكلفة خطّية. فئة Cf كاملة (اتجاه، عرض صفري، وسوم U+E0000-E007F ...)
  // ومحدّدات الصيغة وكل Default_Ignorable_Code_Point تُحذف: هذه الأسطر تصل المالك وتُنسخ إلى التطبيق.
  const TAG_RE = /<[^<>]*>/g;
  const INVISIBLE_RE =
    /[\p{Cf}\p{Default_Ignorable_Code_Point}\u{FE00}-\u{FE0F}\u{E0100}-\u{E01EF}]/gu;
  const RAW_LINE_CAP = 4000;

  function cleanLine(text, max) {
    const raw = String(text === undefined || text === null ? "" : text);
    return clip(
      (raw.length > RAW_LINE_CAP ? raw.slice(0, RAW_LINE_CAP) : raw)
        .replace(TAG_RE, " ")
        .replace(/[<>]/g, " ")
        .replace(/[\u0000-\u001f\u007f-\u009f]/g, " ")
        .replace(INVISIBLE_RE, "")
        .replace(/\s+/g, " ")
        .trim(),
      max,
    );
  }

  /** يلخّص ردّ تنبيهات GitHub العام. يعيد {summary, items} أو null عند الفشل. */
  function summariseAdvisories(workflow, params, response) {
    if (!response || typeof response.statusCode !== "number" || response.statusCode !== 200)
      return null;
    let list;
    try {
      // المتن في data (outputPropertyName) كما يضعه n8n الحقيقي لردّ نصّي كامل، لا في body.
      list = typeof response.data === "string" ? JSON.parse(response.data) : response.data;
    } catch (error) {
      return null;
    }
    if (!Array.isArray(list)) return null;
    const items = list.slice(0, 10).map((a) => {
      const names = Array.isArray(a && a.vulnerabilities)
        ? a.vulnerabilities
            .map((v) => v && v.package && v.package.name)
            .filter(Boolean)
            .slice(0, 3)
            .join("+")
        : "";
      return cleanLine(
        [a && a.ghsa_id, a && a.severity, names, a && a.summary].filter(Boolean).join(" | "),
        160,
      );
    });
    const scope =
      workflow === "dependency_advisory_scan"
        ? "على الحزم الرئيسية (" + SCAN_PACKAGES.length + " حزم بالاسم)"
        : "بدرجة " + params.severity;
    const summary =
      list.length === 0
        ? "لا تنبيهات منشورة " +
          scope +
          " خلال آخر " +
          params.days +
          " يومًا. هذه قراءة لتنبيهات عامة وليست تدقيقًا للنسخ المثبّتة."
        : "عدد التنبيهات المنشورة " +
          scope +
          " خلال آخر " +
          params.days +
          " يومًا: " +
          list.length +
          ". هذه قراءة لتنبيهات عامة وليست تدقيقًا للنسخ المثبّتة.";
    return { summary: clip(summary, 500), items };
  }

  /** ينظّف مفتاح researchCache فقط. لا يلمس النونس ولا الميزانية ولا التكرار. */
  function purgeResearchCache(staticData, scope, now) {
    const sd = isPlainObject(staticData) ? staticData : {};
    const cache = isPlainObject(sd.researchCache) ? sd.researchCache : {};
    const keys = Object.keys(cache);
    let removed = 0;
    const kept = {};
    for (const key of keys) {
      const entry = cache[key];
      const expired =
        !isPlainObject(entry) || typeof entry.expiresAt !== "number" || entry.expiresAt <= now;
      if (scope === "all" || expired) removed += 1;
      else kept[key] = entry;
    }
    sd.researchCache = kept;
    return {
      removed,
      remaining: Object.keys(kept).length,
      summary:
        "حُذف " +
        removed +
        " من مدخلات ذاكرة البحث المؤقتة. المتبقي: " +
        Object.keys(kept).length +
        ".",
    };
  }

  const STATUS_AR = { ok: "سليمة", degraded: "متدهورة", down: "متوقفة" };
  const LABELS = { app: "الصحة العامة", chat: "الدردشة", provider: "مزوّد الويب" };

  /** يلخّص تقييم المراقب الفوري (canary_run_now). */
  function summariseCanary(evaluation) {
    const status = evaluation && STATUS_AR[evaluation.observed] ? evaluation.observed : "down";
    const checks = evaluation && Array.isArray(evaluation.checks) ? evaluation.checks : [];
    return {
      summary: "حالة الفحص الفوري: " + STATUS_AR[status] + ".",
      items: checks
        .slice(0, 10)
        .map((c) =>
          cleanLine(
            (LABELS[c.name] || c.name) +
              ": " +
              (STATUS_AR[c.status] || c.status) +
              (c.detail ? " (" + c.detail + ")" : ""),
            160,
          ),
        ),
    };
  }

  /** يلخّص ناتج عقدة Telegram لاختبار الإشعار. */
  function summariseNotify(out) {
    const delivered = Boolean(out && !out.error && (out.ok === true || out.result));
    return {
      summary: delivered
        ? "وصلت رسالة الاختبار إلى قناة المالك."
        : "تعذّر إرسال رسالة الاختبار. راجع بيانات القناة في n8n.",
      items: [delivered ? "الإرسال: ناجح" : "الإرسال: فشل"],
    };
  }

  if (typeof module !== "undefined" && module.exports) {
    module.exports = {
      CATALOG,
      PARAM_SPECS,
      SCAN_PACKAGES,
      IDEMPOTENCY_TTL_MS,
      IDEMPOTENCY_CAP,
      dispatch,
      recordResult,
      validateParams,
      buildRequest,
      summariseAdvisories,
      purgeResearchCache,
      summariseCanary,
      summariseNotify,
    };
  }
  return module.exports;
})();

const BuildEnvelope = (function () {
  const module = { exports: {} };
  /**
   * build-envelope: يبني غلاف الردّ ويضمن أنه صالح دائمًا.
   *
   * الضمان: لأي مدخل (null، undefined، نص، كائن ناقص، مصفوفات ضخمة، حقول
   * بنوع خاطئ، أخطاء، مهلات) تعود الدالة بغلافٍ يجتاز `validateEnvelope`، وإلا
   * بغلاف ثابت مكتوب حرفيًّا. لا ترمي أبدًا. الجسم المُعاد لا يتجاوز 32 كيلوبايت
   * (سقف التطبيق للردّ) وإلا يُقصّ من الذيل.
   *
   * غلاف البحث:
   *   {v:1, ok, code, requestId, degraded, fetchedAt, providers[], results[]<=6}
   * غلاف المشغّل:
   *   {v:1, ok, code, requestId, result:{summary<=500, items[]<=10}|null}
   *
   * الرموز المسموحة صراحةً من الخارج هي رموز الفشل فقط. رمز ok وno_results
   * يُشتقّان من المزوّدين والنتائج؛ لا يُصرَّح بهما، فلا ادّعاء نجاح بلا نتائج.
   */

  const RESEARCH_CODES = [
    "ok",
    "no_results",
    "all_providers_failed",
    "auth_failed",
    "bad_request",
    "budget_exhausted",
    "internal",
  ];
  const EXPLICIT_FAILURE_CODES = [
    "all_providers_failed",
    "auth_failed",
    "bad_request",
    "budget_exhausted",
    "internal",
  ];
  const RUNNER_CODES = [
    "ok",
    "unknown_workflow",
    "bad_params",
    "auth_failed",
    "already_done",
    "budget_exhausted",
    "internal",
  ];
  const STATUSES = ["ok", "error", "timeout", "skipped"];
  // مفاتيح العنصر الداخلية كما يفرضها مخطط التطبيق الصارم (strictObject): مفتاح زائد يُرفض الغلاف كلّه عنده.
  const PROVIDER_KEYS = ["id", "status", "ms", "n"];
  const RESULT_KEYS = ["title", "url", "snippet", "publishedAt", "provider"];
  const MAX_BODY_BYTES = 32768;
  // سقف مصفوفة المزوّدين في عقد التطبيق (PROVIDER_MAX في schema.ts): ما فوقه يُرفض الغلاف كلّه عند التطبيق.
  const MAX_PROVIDERS = 8;
  const EPOCH_ISO = "1970-01-01T00:00:00.000Z";
  const ID_RE = /^[A-Za-z0-9_-]{1,64}$/;
  const UUID_LIKE_RE =
    /^[0-9a-fA-F]{8}-[0-9a-fA-F]{4}-[0-9a-fA-F]{4}-[0-9a-fA-F]{4}-[0-9a-fA-F]{12}$/;
  const NONCE_RE = /^[0-9a-f]{32}$/;
  const HTTPS_RE = /^https:\/\/[^\s"'<>\\]+$/;

  // الوسم بلا < داخله فالكلفة خطّية (النمط /<[^>]*>/ تربيعي على نصّ مليء بـ< بلا >).
  const TAG_RE = /<[^<>]*>/g;
  // فئة Cf كاملة (اتجاه، عرض صفري، وسوم U+E0000-E007F، U+061C، U+00AD ...) + محدّدات الصيغة + كل
  // Default_Ignorable_Code_Point (كما في merge-rank.js ومعقِّم التطبيق).
  const INVISIBLE_RE =
    /[\p{Cf}\p{Default_Ignorable_Code_Point}\u{FE00}-\u{FE0F}\u{E0100}-\u{E01EF}]/gu;
  const RAW_FIELD_CAP = 4000;

  function cleanText(value, max) {
    if (typeof value !== "string") return "";
    const text = (value.length > RAW_FIELD_CAP ? value.slice(0, RAW_FIELD_CAP) : value)
      .replace(TAG_RE, " ")
      .replace(/[<>]/g, " ")
      .replace(/[\u0000-\u001f\u007f-\u009f]/g, " ")
      .replace(INVISIBLE_RE, "")
      .replace(/\s+/g, " ")
      .trim();
    const chars = Array.from(text);
    return chars.length <= max
      ? text
      : chars
          .slice(0, max - 1)
          .join("")
          .trimEnd() + "…";
  }

  function safeIso(value) {
    try {
      const ms = typeof value === "number" ? value : Date.parse(String(value));
      if (isFinite(ms)) return new Date(ms).toISOString();
    } catch (error) {
      // يسقط إلى الاحتياط أدناه
    }
    try {
      return new Date().toISOString();
    } catch (error) {
      return EPOCH_ISO;
    }
  }

  function safeInt(value, min, max) {
    const n = Math.floor(Number(value));
    if (!isFinite(n)) return min;
    return Math.min(max, Math.max(min, n));
  }

  function safeRequestId(value) {
    return typeof value === "string" && ID_RE.test(value) ? value : "";
  }

  function normaliseProviders(value) {
    if (!Array.isArray(value)) return [];
    const out = [];
    for (const item of value.slice(0, MAX_PROVIDERS)) {
      if (!item || typeof item !== "object") continue;
      const id = cleanText(item.id, 32);
      if (!id) continue;
      out.push({
        id,
        status: STATUSES.indexOf(item.status) === -1 ? "error" : item.status,
        ms: safeInt(item.ms, 0, 60000),
        n: safeInt(item.n, 0, 100),
      });
    }
    return out;
  }

  function normaliseIsoOrNull(value) {
    if (typeof value !== "string" || value.length === 0) return null;
    const ms = Date.parse(value);
    if (!isFinite(ms)) return null;
    try {
      return new Date(ms).toISOString();
    } catch (error) {
      return null;
    }
  }

  function normaliseResults(value) {
    if (!Array.isArray(value)) return [];
    const out = [];
    for (const item of value.slice(0, 50)) {
      if (!item || typeof item !== "object") continue;
      const url = typeof item.url === "string" ? item.url.trim() : "";
      if (url.length === 0 || url.length > 300 || !HTTPS_RE.test(url)) continue;
      const provider = cleanText(item.provider, 32);
      if (!provider) continue;
      out.push({
        title: cleanText(item.title, 120) || url.slice(8, 60),
        url,
        snippet: cleanText(item.snippet, 300),
        publishedAt: normaliseIsoOrNull(item.publishedAt),
        provider,
      });
      if (out.length >= 6) break;
    }
    return out;
  }

  /** مدقّق بنيوي مكافئ لما يفعله zod الصارم عند التطبيق. يعيد مصفوفة مشاكل. */
  function validateEnvelope(envelope) {
    const problems = [];
    const e = envelope;
    if (!e || typeof e !== "object" || Array.isArray(e)) return ["not_object"];
    const allowed = ["v", "ok", "code", "requestId", "degraded", "fetchedAt", "providers", "results"];
    for (const key of Object.keys(e)) if (allowed.indexOf(key) === -1) problems.push("extra:" + key);
    for (const key of allowed) if (!(key in e)) problems.push("missing:" + key);
    if (e.v !== 1) problems.push("v");
    if (typeof e.ok !== "boolean") problems.push("ok");
    if (RESEARCH_CODES.indexOf(e.code) === -1) problems.push("code");
    if (typeof e.requestId !== "string") problems.push("requestId");
    if (typeof e.degraded !== "boolean") problems.push("degraded");
    if (typeof e.fetchedAt !== "string" || !isFinite(Date.parse(e.fetchedAt))) {
      problems.push("fetchedAt");
    }
    if (!Array.isArray(e.providers)) problems.push("providers");
    else {
      e.providers.forEach((p, i) => {
        if (!p || typeof p !== "object") return problems.push("provider:" + i);
        for (const key of Object.keys(p)) {
          if (PROVIDER_KEYS.indexOf(key) === -1) problems.push("provider.extra:" + key + ":" + i);
        }
        if (typeof p.id !== "string" || p.id.length === 0) problems.push("provider.id:" + i);
        if (STATUSES.indexOf(p.status) === -1) problems.push("provider.status:" + i);
        if (!Number.isInteger(p.ms) || p.ms < 0) problems.push("provider.ms:" + i);
        if (!Number.isInteger(p.n) || p.n < 0) problems.push("provider.n:" + i);
      });
    }
    if (!Array.isArray(e.results) || e.results.length > 6) problems.push("results");
    else {
      e.results.forEach((r, i) => {
        if (!r || typeof r !== "object") return problems.push("result:" + i);
        for (const key of Object.keys(r)) {
          if (RESULT_KEYS.indexOf(key) === -1) problems.push("result.extra:" + key + ":" + i);
        }
        if (typeof r.title !== "string" || Array.from(r.title).length > 120) {
          problems.push("result.title:" + i);
        }
        if (typeof r.url !== "string" || r.url.length > 300 || !HTTPS_RE.test(r.url)) {
          problems.push("result.url:" + i);
        }
        if (typeof r.snippet !== "string" || Array.from(r.snippet).length > 300) {
          problems.push("result.snippet:" + i);
        }
        if (
          r.publishedAt !== null &&
          (typeof r.publishedAt !== "string" || !isFinite(Date.parse(r.publishedAt)))
        ) {
          problems.push("result.publishedAt:" + i);
        }
        if (typeof r.provider !== "string" || r.provider.length === 0) {
          problems.push("result.provider:" + i);
        }
      });
    }
    const okShouldBe = e.code === "ok" || e.code === "no_results";
    if (e.ok !== okShouldBe) problems.push("ok_code_mismatch");
    if (e.code === "ok" && Array.isArray(e.results) && e.results.length === 0) {
      problems.push("ok_without_results");
    }
    return problems;
  }

  function literalFallback(requestId, fetchedAt) {
    return {
      v: 1,
      ok: false,
      code: "internal",
      requestId: safeRequestId(requestId),
      degraded: true,
      fetchedAt: fetchedAt || EPOCH_ISO,
      providers: [],
      results: [],
    };
  }

  function byteLength(text) {
    return Buffer.byteLength(text, "utf8");
  }

  /**
   * @param {object} [input] {requestId, code, providers, results, now}
   * @returns {{envelope: object, body: string}}
   */
  function buildEnvelope(input) {
    let requestId = "";
    let fetchedAt = EPOCH_ISO;
    try {
      const safe = input && typeof input === "object" ? input : {};
      requestId = safeRequestId(safe.requestId);
      fetchedAt = safeIso(safe.now);
      const explicit = EXPLICIT_FAILURE_CODES.indexOf(safe.code) !== -1;
      // ردّ فشل صريح (مصادقة، طلب سيئ، ميزانية، داخلي) لا يحمل مزوّدين ولا نتائج.
      const keepsProviders = !explicit || safe.code === "all_providers_failed";
      const providers = keepsProviders ? normaliseProviders(safe.providers) : [];
      let results = explicit ? [] : normaliseResults(safe.results);
      let code;
      if (explicit) {
        code = safe.code;
      } else if (results.length > 0) {
        code = "ok";
      } else {
        const attempted = providers.filter((p) => p.status !== "skipped");
        const anyOk = providers.some((p) => p.status === "ok");
        code = attempted.length === 0 || !anyOk ? "all_providers_failed" : "no_results";
      }
      if (code === "all_providers_failed") results = [];
      const ok = code === "ok" || code === "no_results";
      const degraded = !ok || providers.some((p) => p.status === "error" || p.status === "timeout");
      const envelope = { v: 1, ok, code, requestId, degraded, fetchedAt, providers, results };
      const body = JSON.stringify(envelope);
      if (validateEnvelope(envelope).length > 0 || byteLength(body) > MAX_BODY_BYTES) {
        throw new Error("invalid_envelope");
      }
      return { envelope, body };
    } catch (error) {
      const envelope = literalFallback(requestId, fetchedAt);
      return { envelope, body: JSON.stringify(envelope) };
    }
  }

  function normaliseItems(value) {
    if (!Array.isArray(value)) return [];
    const out = [];
    for (const item of value.slice(0, 10)) {
      const text = cleanText(typeof item === "number" ? String(item) : item, 160);
      if (text) out.push(text);
    }
    return out;
  }

  /**
   * @param {object} [input] {requestId, code, result:{summary, items}, now}
   * @returns {{envelope: object, body: string}}
   */
  function buildRunnerEnvelope(input) {
    let requestId = "";
    try {
      const safe = input && typeof input === "object" ? input : {};
      requestId = safeRequestId(safe.requestId);
      const code = RUNNER_CODES.indexOf(safe.code) === -1 ? "internal" : safe.code;
      const keep = code === "ok" || code === "already_done";
      let result = null;
      if (keep && safe.result && typeof safe.result === "object") {
        result = {
          summary: cleanText(safe.result.summary, 500),
          items: normaliseItems(safe.result.items),
        };
      }
      if (keep && result === null) {
        return buildRunnerEnvelope({ requestId, code: "internal" });
      }
      const envelope = { v: 1, ok: keep, code, requestId, result };
      return { envelope, body: JSON.stringify(envelope) };
    } catch (error) {
      const envelope = { v: 1, ok: false, code: "internal", requestId, result: null };
      return { envelope, body: JSON.stringify(envelope) };
    }
  }

  /** يستخلص نونس الطلب ومعرّفه من إدخال n8n الخام (دون الوثوق بهما) لتوقيع ردّ الفشل. */
  function contextFromWebhook(webhookJson) {
    const out = { nonce: "", requestId: "" };
    try {
      const headers = (webhookJson && webhookJson.headers) || {};
      for (const key of Object.keys(headers)) {
        if (key.toLowerCase() === "x-nx-nonce") {
          const value = String(Array.isArray(headers[key]) ? headers[key][0] : headers[key])
            .trim()
            .toLowerCase();
          if (NONCE_RE.test(value)) out.nonce = value;
        }
      }
      const body = webhookJson && webhookJson.body;
      if (body && typeof body === "object" && UUID_LIKE_RE.test(String(body.requestId))) {
        out.requestId = body.requestId;
      }
    } catch (error) {
      // يبقى فارغًا
    }
    return out;
  }

  if (typeof module !== "undefined" && module.exports) {
    module.exports = {
      buildEnvelope,
      buildRunnerEnvelope,
      validateEnvelope,
      contextFromWebhook,
      RESEARCH_CODES,
      RUNNER_CODES,
      MAX_BODY_BYTES,
      MAX_PROVIDERS,
    };
  }
  return module.exports;
})();

